# Generated by build.py from recipe.yml for recipe stomp-send-and-read-over-mqtt. Do not edit.
Set-Location $PSScriptRoot
$server0 = Start-Process surl -ArgumentList '--allow-anonymous', '--topic', '"devices/#;retain"', '--idle-timeout', '1', 'stomp://127.0.0.1:8080/', 'mqtt://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s -d on stomp://127.0.0.1:8080/topic/devices/lamp/state --next -s mqtt://127.0.0.1:8081/devices/lamp/state } finally { Stop-Process $server0 }
